// Une entreprise trouvée = un item prospect (clés = colonnes du CRM).
const form = $('Formulaire — sourcing').first().json;
const secteur = (form['Secteur'] || '').toString().trim();
const ville = (form['Ville'] || '').toString().trim();
const places = $json.places || [];
return places.map((p) => ({ json: {
  prospect: p.displayName?.text || '',
  type: secteur,
  city: ville,
  phone: p.nationalPhoneNumber || '',
  website: p.websiteUri || '',
  rating: p.rating ?? '',
  reviews: p.userRatingCount ?? '',
  address: p.formattedAddress || '',
} })).filter((it) => it.json.prospect);

// Recolle le SIREN Pappers sur le prospect d'origine (même index).
// Si Pappers a échoué (pas de clé, quota…), on passe sans bloquer.
const base = $('Mapper prospects').all();
return $input.all().map((it, i) => {
  const src = base[i]?.json || {};
  const r = (it.json?.resultats || [])[0] || {};
  const notes = r.siren ? `SIREN ${r.siren}${r.forme_juridique ? ' · ' + r.forme_juridique : ''}` : '';
  return { json: { ...src, siren: r.siren || '', notes } };
});

// Recolle l'email direct du dirigeant (Apollo) — optionnel lui aussi.
const base = $('Fusion Pappers').all();
return $input.all().map((it, i) => {
  const src = base[i]?.json || {};
  const p = (it.json?.people || [])[0] || {};
  const email = p.email && !String(p.email).includes('email_not_unlocked') ? String(p.email).toLowerCase() : '';
  const contact = p.name || '';
  return { json: { ...src, email, contact } };
});

// Ne garde que les VRAIS nouveaux : ni le nom ni l'email ne sont déjà au CRM.
const existing = $input.all().map((r) => r.json || {});
const norm = (s) => String(s || '').toLowerCase().trim();
const seenName = new Set(existing.map((r) => norm(r.prospect || r.Prospect)).filter(Boolean));
const seenEmail = new Set(existing.map((r) => norm(r.email || r.Email)).filter(Boolean));
const now = new Date().toISOString().slice(0, 16).replace('T', ' ');
const fresh = ($('Agréger').first().json.prospects || []).filter((p) => {
  const name = norm(p.prospect);
  const mail = norm(p.email);
  if (!name || seenName.has(name)) return false;
  if (mail && seenEmail.has(mail)) return false;
  return true;
});
return fresh.map((p) => ({ json: {
  ...p,
  stage: 'prospect',
  history: `[${now}] Sourcing auto — Maps${p.siren ? '+Pappers' : ''}${p.email ? '+Apollo' : ''} (${p.type})`,
} }));
